head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[image > M > getAlt]<br/>Image 컴포넌트에 설정된 alt 속성값을 반환합니다.",
    "validation" : [
        "String 타입으로 alt 속성값을 반환합니다.",
        "alt 속성값이 없는 경우 ''(Empty String)을 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // 정적 select1 초기값 설정 (alt : 미설정)
    con_alt.setValue("");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let cAlt = con_alt.getValue();

    let lblAlt = (cAlt === "") ? "미설정" : cAlt;

    $c.gcm.createLabel('label="[현재] alt = ' + lblAlt + '\n[절차] con_alt 값 변경 -> Target 재생성 -> getAlt 버튼 클릭\n[확인] 반환값은 따옴표로 감싸 typeof 및 길이와 함께 출력되므로, 빈 문자열 반환과 null 을 구분해서 확인합니다\n[확인] 마크업의 alt 속성 존재 여부를 반환값과 함께 출력하므로 두 값을 대조합니다"', '', 'label1');

    // 조건 설정 (createCList 는 빈 값 property 를 제외하므로 미설정 시 alt 속성 자체가 선언되지 않는다)
    let properties = {
        alt : cAlt,
    };

    let cList = $c.gcm.createCList(properties);

    await $c.gcm.createBasicImage(cList);
}



// getAlt 호출 및 validation 항목별 판정 출력
scwin.btn_getAlt_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    let img = target1.render;

    // 반환값 (엔진은 IDL 프로퍼티 render.alt 를 반환한다)
    let ret = target1.getAlt();

    // 마크업 상의 alt 속성 (속성 자체가 없으면 null)
    let attrVal = img.getAttribute("alt");

    let strRet  = "'" + ret + "' (typeof " + (typeof ret) + " / 길이 " + ret.length + ")";
    let strAttr = (attrVal === null) ? "없음 (getAttribute 결과 null)" : "존재 ('" + attrVal + "')";

    if (attrVal === null || attrVal === "") {
        bottom.setReturnValue("[2] alt 미설정 -> getAlt() 반환값 : " + strRet + " / 마크업 alt 속성 : " + strAttr);
    }
    else {
        bottom.setReturnValue("[1] alt 설정 -> getAlt() 반환값 : " + strRet + " / 마크업 alt 속성 : " + strAttr);
    }
};
